--- src/summary.ts ---
/**
 * Counts the occurrences of each status value in the provided array.
 *
 * @param items - An array of objects that each have a `status` string property.
 * @returns A record mapping each distinct status to its count.
 *
 * @example
 * countByStatus([
 *   { status: "open" },
 *   { status: "closed" },
 *   { status: "open" },
 * ]);
 * // => { open: 2, closed: 1 }
 */
export function countByStatus(
  items: Array<{ status: string }>
): Record<string, number> {
  return items.reduce<Record<string, number>>((counts, { status }) => {
    counts[status] = (counts[status] ?? 0) + 1;
    return counts;
  }, {});
}

