/** An object that carries a `status` string field. */
export interface HasStatus {
  status: string;
  [key: string]: unknown;
}

/**
 * Count occurrences of each distinct `status` value in the supplied array.
 *
 * @example
 * countByStatus([
 *   { status: "open" },
 *   { status: "closed" },
 *   { status: "open" },
 * ]);
 * // → { open: 2, closed: 1 }
 */
export function countByStatus(items: HasStatus[]): Record<string, number> {
  return items.reduce<Record<string, number>>((acc, item) => {
    acc[item.status] = (acc[item.status] ?? 0) + 1;
    return acc;
  }, {});
}

